(function () {
  const { title, h, list, fx, card, flow, cols, split, tbl, svg, at } = VK;
  // token chips: "~w" struck out, "*w" changed/highlight, "+w" context, "w/TAG" adds a tag under the word
  const tks = (k, label, words) => at(k, `<div class="tks"><em>${label}</em>${words.map(w => { let c = ""; if (w[0] === "~") { c = "x"; w = w.slice(1); } else if (w[0] === "*") { c = "c"; w = w.slice(1); } else if (w[0] === "+") { c = "k"; w = w.slice(1); } const [a, t] = w.split("/"); return `<span class="${c}">${a}${t ? `<i>${t}</i>` : ""}</span>`; }).join("")}</div>`);
  // probability bar
  const pbar = (k, p, a, b) => at(k, `<div class="pbar"><b style="width:${p * 100}%">${a}</b><i>${b}</i></div>`);
  // parse tree for "She walked a small dog over a street"
  const PT = {
    S: [300, 25, "S", 0], NP1: [45, 70, "NP", 1], VP: [330, 70, "VP", 1],
    Pro: [45, 245, "Pronoun", 2], w1: [45, 290, "She", 2, "w"],
    VP2: [190, 115, "VP", 3], PP: [500, 115, "PP", 3],
    V: [120, 245, "Verb", 4], w2: [120, 290, "walked", 4, "w"], NP2: [255, 160, "NP", 4],
    A1: [195, 245, "Article", 4], w3: [195, 290, "a", 4, "w"], AP: [265, 200, "AP", 4], Adj: [265, 245, "Adjective", 4], w4: [265, 290, "small", 4, "w"],
    N1: [340, 245, "Noun", 4], w5: [340, 290, "dog", 4, "w"],
    Pr: [425, 245, "Prep", 5], w6: [425, 290, "over", 5, "w"], NP3: [540, 160, "NP", 5],
    A2: [500, 245, "Article", 5], w7: [500, 290, "a", 5, "w"], N2: [580, 245, "Noun", 5], w8: [580, 290, "street", 5, "w"]
  };
  const PE = [["S", "NP1"], ["S", "VP"], ["NP1", "Pro"], ["Pro", "w1"], ["VP", "VP2"], ["VP", "PP"], ["VP2", "V"], ["V", "w2"], ["VP2", "NP2"], ["NP2", "A1"], ["A1", "w3"], ["NP2", "AP"], ["AP", "Adj"], ["Adj", "w4"], ["NP2", "N1"], ["N1", "w5"], ["PP", "Pr"], ["Pr", "w6"], ["PP", "NP3"], ["NP3", "A2"], ["A2", "w7"], ["NP3", "N2"], ["N2", "w8"]];
  const ptree = () => `<svg class="pt" viewBox="0 0 630 305">${PE.map(([a, b]) => { const [x1, y1] = PT[a], [x2, y2, , k] = PT[b]; return `<g class="vk-i" data-s="${k}"><line x1="${x1}" y1="${y1 + 9}" x2="${x2}" y2="${y2 - 10}"/></g>`; }).join("")}${Object.values(PT).map(([x, y, l, k, c = ""]) => { const w = l.length * 7.6 + 14; return `<g class="vk-i n ${c}" data-s="${k}"><rect x="${x - w / 2}" y="${y - 11}" width="${w}" height="22" rx="6"/><text x="${x}" y="${y + 4.5}">${l}</text></g>`; }).join("")}</svg>`;

  const { stg, act, fix, tag, say, zone, bar, J } = VK;
  // autocomplete: next-word bars after "Mando protects"
  const ac = (k) => at(k, `<div class="ac8"><div class="kb8">Mando protects <b>|</b></div><div class="smx5">${[["Grogu", 3], ["the", 1], ["himself", 1]].map(([w, c]) => `<div class="brow"><em>${w} <small>${c} of 5</small></em><div class="trk">${bar({ [k]: c * 20 }, "g")}</div><i>${(c / 5).toFixed(1)}</i></div>`).join("")}</div></div>`);
  // a 3-letter window sliding over "excellence"
  const EX = [..."excellence"];
  const chr = `<div class="chr8">${EX.map(c => `<span>${c}</span>`).join("")}<div class="win8" data-run='${J({ 1: [[0, 0], [0, 0], [10, 0], [20, 0], [30, 0], [40, 0], [50, 0], [60, 0], [70, 0]] })}' data-dur="7000" style="opacity:0"></div></div>`;
  // bag of words: order is thrown away
  const BW = ["my", "grandson", "loved", "it", "so", "much", "fun"];
  const BJ = [[70, 52], [84, 72], [76, 80], [90, 50], [64, 74], [84, 48], [72, 64]];
  const bag = [fix(zone("the bag: order gone, counts kept", 26, 10, "bag8 top"), 78, 62, 1)]
    .concat(BW.map((w, i) => `<div class="a" data-run='${J({ 0: [[8 + i * 8, 20]], 1: [[8 + i * 8, 20], [8 + i * 8, 20], BJ[i]] })}' data-dur="2400" style="opacity:0">${tag(w, "chip")}</div>`))
    ;
  // balance scale: positive vs negative score
  const scale = `<svg class="vk-g sc8" viewBox="0 0 260 120"><path class="bs8" d="M120 112 L140 112 L130 62 Z"/><g class="bm8" data-p="0:130,60,1,1,0 3:130,60,1,1,-12"><line x1="-100" y1="0" x2="100" y2="0"/><line x1="-90" y1="0" x2="-90" y2="22"/><line x1="90" y1="0" x2="90" y2="22"/>
    <rect class="pp8" x="-122" y="22" width="64" height="24" rx="4"/><text x="-90" y="39" text-anchor="middle">${"S₊ 0.000141"}</text><rect class="pn8" x="58" y="22" width="64" height="24" rx="4"/><text x="90" y="39" text-anchor="middle">S₋ 0.000065</text></g>
    <text class="vk-i lt8" data-s="3" x="215" y="112" text-anchor="middle">positive wins</text></svg>`;
  // one zero kills the product
  const ZC = ["0.49", "0.30", "0", "0.32", "0.30"];
  const zero = `<div class="zc8">${ZC.map((v, i) => `<span class="${v === "0" ? "z" : ""}">${v}</span>${i < 4 ? "<em>×</em>" : ""}`).join("")}<em>=</em><b data-t='${J({ 0: "0" })}'>0</b></div>`;
  // fishing net: precision and recall
  const IN_F = [[20, 32], [28, 46], [36, 30], [22, 62], [32, 68], [40, 52]], IN_B = [[28, 28], [42, 70]];
  const OUT_F = [[62, 30], [74, 62], [86, 40], [92, 74]], OUT_B = [[58, 58], [66, 80], [70, 42], [80, 26], [82, 80], [90, 56], [62, 70], [76, 50]];
  const fishy = (pts, cls, on) => pts.map(([x, y]) => fix(`<i class="${cls}" data-on="${on}"></i>`, x, y)).join("");
  const net = [fix(zone("result set (the net)", 30, 12, "net8"), 30, 50), fishy(IN_F, "fs8", "1:lit8"), fishy(IN_B, "bt8", "1:lit8 2:"), fishy(OUT_F, "fs8", "2:lit8"), fishy(OUT_B, "bt8", ""),
    fix(tag(say({ 0: "green = relevant fish, grey = old boots", 1: "precision: 6 fish of 8 caught = <b>0.75</b>", 2: "recall: 6 of all 10 fish = <b>0.60</b>", 3: "F = harmonic mean ≈ <b>0.667</b>" }), "hi"), 62, 8)];
  // gradient bars over time (reuses the L5 bar style)
  const vg = (w, k, cls) => `<div class="vg5 ${cls}">` + [0, 1, 2, 3, 4].map(t => { const hgt = w < 1 ? 100 * w ** (4 - t) : 100 / w ** t; return `<div><i data-st='${J({ [k]: "height:" + hgt.toFixed(1) + "%" })}' style="height:0%;transition-delay:${(4 - t) * 0.3}s"></i><span>${t === 4 ? "now" : "t−" + (4 - t)}</span></div>`; }).join("") + `</div>`;
  // weighted value vectors: 0.3 × [2, 0] + 0.7 × [0, 2]
  const VX = x => 30 + x * 70, VY = y => 160 - y * 70;
  const arr = (x1, y1, x2, y2, cls, k) => `<line class="vx8 ${cls} ${k != null ? "vk-i" : ""}" ${k != null ? `data-s="${k}"` : ""} x1="${VX(x1)}" y1="${VY(y1)}" x2="${VX(x2)}" y2="${VY(y2)}" marker-end="url(#l8ah)"/>`;
  const vecs = `<svg class="vk-g vv8" viewBox="0 0 200 175"><defs><marker id="l8ah" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z"/></marker></defs>
    <line class="ax8" x1="30" y1="160" x2="190" y2="160"/><line class="ax8" x1="30" y1="160" x2="30" y2="10"/>
    ${arr(0, 0, 2, 0, "v1", null)}${arr(0, 0, 0, 2, "v2", null)}<text class="lt8" x="${VX(2)}" y="${VY(0) - 6}" text-anchor="end">v₁ [2, 0]</text><text class="lt8" x="${VX(0) + 6}" y="${VY(2) + 4}">v₂ [0, 2]</text>
    ${arr(0, 0, 0.6, 0, "w1", 1)}${arr(0, 0, 0, 1.4, "w2", 1)}
    <g class="vk-i" data-s="2"><line class="gd8" x1="${VX(0.6)}" y1="${VY(0)}" x2="${VX(0.6)}" y2="${VY(1.4)}"/><line class="gd8" x1="${VX(0)}" y1="${VY(1.4)}" x2="${VX(0.6)}" y2="${VY(1.4)}"/>${arr(0, 0, 0.6, 1.4, "out", null)}<text class="lt8 b" x="${VX(0.6) + 6}" y="${VY(1.4) - 4}">[0.6, 1.4]</text></g></svg>`;

  VIDEO_LESSONS.l8 = {
    title: "L8: Natural Language Processing", chapters: [
      { t: "What NLP is", sec: [], scenes: [
        { v: title("Natural Language Processing", "Week 8 lesson") + list([[1, "What <b>NLP</b> is, its tasks, and the <b>pipeline</b> that cleans text"], [2, "<b>Grammar</b> and parse trees (optional)"], [3, "<b>Language models</b>: n-grams and bag of words"], [4, "<b>Word representation</b>: one-hot vs embeddings, <b>word2vec</b>"], [5, "<b>Naive Bayes</b> sentiment analysis, then <b>information retrieval</b> (optional)"], [6, "Sequence models: <b>RNNs</b>, <b>attention</b>, <b>Transformers</b>"]]),
          n: ["Welcome to week 8: natural language processing, or NLP. Everything this week answers one question. How can a program take messy human language and turn it into something it can compute with?",
            "We'll start with what NLP is, the tasks it covers, and the pipeline that cleans raw text before any learning happens.",
            "Then grammar and parse trees. The course marks this as optional, but it's short and it explains why language is hard.",
            "Then language models: n-grams, which predict the next item, and bag of words, which turns text into counts.",
            "Then how to represent a word as numbers: one-hot vectors versus learned word embeddings, and how word2vec learns them.",
            "Then the main worked example of the week, sentiment analysis with Naive Bayes, followed by information retrieval, with TF-IDF, precision and recall.",
            "And finally the sequence side of this topic, which the revision notes and quiz test: recurrent networks, attention, and the Transformer. Let's go."] },
        { v: h("Why we want agents to handle language") + card(0, "", "<b>NLP</b>: computational techniques that let an agent <b>understand</b> human language (written or spoken) and use the huge amount of <b>knowledge</b> stored in it.") + cols(card(1, "tip", "<b>1. Communicate with humans</b><br>Chatbots, smart assistants, automated phone systems."), card(2, "tip", "<b>2. Learn from written language</b><br>Text is the biggest store of knowledge. An agent that can read doesn't need hand-fed structured data.")) + card(3, "warn", "Why it's hard: language can't be pinned down as a <b>fixed list</b> of valid sentences, it's <b>ambiguous</b>, and it's <b>huge and always changing</b>."),
          n: ["Natural language processing is the set of computational techniques that let an agent understand expressions written or spoken in a human language, and make use of the huge amount of knowledge stored in that form. Humans are the only species that can send an unlimited variety of messages about any topic using discrete signs, so a big share of human knowledge lives in text.",
            "There are two main reasons we want agents to handle language. The first is to communicate with humans. Chatbots, smart assistants and automated phone systems all depend on it.",
            "The second is to learn from written language. Text is the biggest store of knowledge we have, so an agent that can read can learn without someone hand-feeding it structured data.",
            "Why is this hard? Three reasons. Natural languages can't be pinned down as a fixed list of valid sentences. They are ambiguous, so one sentence can mean several things. And they are huge and keep changing, as people invent new words and new ways of using them."] },
        { v: h("Typical NLP tasks") + split(tbl(["Text classification", "Example"], [[0, "<b>Sentiment analysis</b>", "Review → positive or negative"], [1, "<b>Language identification</b>", "French vs Spanish"], [1, "<b>Spam detection</b>", "Spam vs ham (not spam)"], [1, "<b>Genre classification</b>", "News, legal, scientific…"]], "sm"), tbl(["Other tasks", "What it does"], [[2, "<b>Information retrieval</b>", "Find documents for a query (web search)"], [2, "<b>Information extraction</b>", "Pull objects and relations (companies and founders)"], [3, "<b>Summarisation</b>", "Shorter version of a text"], [3, "<b>Machine translation</b>", "English → Indonesian"], [4, "<b>Named entity recognition</b>", "Tag a city, person, company"], [4, "<b>Speech recognition</b>", "Speech → written words"], [5, "<b>Word sense disambiguation</b>", "“bank”: river edge or money?"]], "sm"), "even"),
          n: ["Most everyday NLP work is a specific information-seeking task. The biggest family is text classification: give a text one label from a fixed set. Sentiment analysis decides whether a review or comment is positive or negative. It's the running example this week.",
            "The others in that family: language identification, which works out what language a text is in, spam detection, which labels an email as spam or ham, meaning not spam, and genre classification, which decides whether a document is a news story, a legal document, a scientific article and so on.",
            "Outside classification, information retrieval finds documents relevant to a query, like web search. Information extraction skims text for a class of objects and the relationships between them, for example pulling company names and their founders out of news articles.",
            "Automatic summarisation produces a shorter version of a text. Machine translation translates from a source language to a target language, say English to Indonesian.",
            "Named entity recognition finds the names of things in a document and decides what class each belongs to: a city, a person, a company. Speech recognition writes down the words in a piece of speech.",
            "And word sense disambiguation picks the right meaning of a word that has several, using context. Bank could be the edge of a river or a place that holds money. The sentence around it decides."] }
      ] },
      { t: "The NLP pipeline", sec: [], scenes: [
        { v: h("Cleaning text before learning") + tbl(["Step", "What happens", "Example"], [[0, "1. <b>Segmentation</b>", "Document → sentences (at full stops)", "Paragraph → 5 sentences"], [1, "2. <b>Tokenisation</b>", "Sentence → words (tokens)", "She walked home → she, walked, home"], [2, "3. <b>Stop words</b>", "Drop words with little meaning", "Remove are, the"], [3, "4. <b>Stemming</b>", "Chop prefixes and suffixes", "skipping, skips, skipped → skip"], [4, "5. <b>Lemmatisation</b>", "Dictionary base form (lemma)", "ran → run"], [5, "6. <b>POS tagging</b>", "Noun, verb, article…", "walked → verb"], [6, "7. <b>Named entities</b>", "People, places, movies…", "Sydney → location"], [7, "8. <b>Learning</b>", "Train e.g. Naive Bayes", "Review → positive"]], "sm"),
          n: ["Before any learning, raw text has to be prepared. The intro video compares this to teaching a child to read for the first time. Step one is segmentation: break the document into sentences, usually along punctuation like full stops.",
            "Step two is tokenisation: break each sentence into words, where each word is a token. She walked home becomes three tokens: she, walked, home. Remember this one. The quick check question in the video asks which technique gets the words out of a sentence, and the answer is tokenisation.",
            "Step three, stop word removal: drop words that add little meaning and mostly keep the sentence smooth, like are and the.",
            "Step four, stemming: cut words down to a shared stem by stripping prefixes and suffixes. Skipping, skips and skipped all share one stem.",
            "Step five, lemmatisation: map each word to its dictionary base form, called the lemma, handling tense, mood and similar changes. Ran maps to run.",
            "Step six, part of speech tagging: label each word as a noun, verb, article and so on.",
            "Step seven, named entity tagging: flag names of people, places, movies and similar. Sydney gets tagged as a location.",
            "And step eight, learning: train a machine learning model, for example Naive Bayes, on the prepared data, to learn sentiment or other patterns."] },
        { v: h("Watch one sentence go through it") + tks(0, "1. Segment", ["The kids were skipping happily in Sydney.", "They loved it!"]) + tks(1, "2. Tokenise", ["the", "kids", "were", "skipping", "happily", "in", "sydney"]) + tks(2, "3. Stop words", ["~the", "kids", "~were", "skipping", "happily", "~in", "sydney"]) + tks(3, "4. Stem", ["*kid", "*skip", "*happili", "sydney"]) + tks(4, "5. Lemmatise", ["*kid", "*skip", "happily", "sydney"]) + tks(5, "6. POS tags", ["kid/noun", "skip/verb", "happily/adverb", "sydney/proper noun"]) + tks(6, "7. Entities", ["kid", "skip", "happily", "*sydney/LOCATION"]) + card(7, "warn", "<b>Stemming</b>: rough chop, may leave a non-word (happili). <b>Lemmatisation</b>: vocabulary → real word (ran → run)."),
          n: ["Let's push one small document through. Segmentation splits it at the punctuation into two sentences: The kids were skipping happily in Sydney, and, They loved it.",
            "Tokenisation splits the first sentence into tokens, usually lower-cased: the, kids, were, skipping, happily, in, sydney.",
            "Stop word removal drops the, were and in. They glue the sentence together but say little about its content.",
            "Stemming chops endings by rule. Kids becomes kid, skipping becomes skip, and happily becomes happili, which isn't a real word. That's typical of stemming.",
            "Lemmatisation uses a vocabulary, so it returns real base words: kid, skip, and happily stays happily. If were had survived, its lemma would be be.",
            "Part of speech tagging labels each token: kid is a noun, skip a verb, happily an adverb, Sydney a proper noun.",
            "Named entity tagging spots that Sydney is a location.",
            "The video blurs stemming and lemmatisation a little, so here's the clean distinction for the exam. Stemming is a rough rule-based chop that may leave a non-word. Lemmatisation uses vocabulary knowledge to return a real base word."] }
      ] },
      { t: "Grammar and parsing (optional)", sec: [], scenes: [
        { v: h("Syntax, semantics and grammars") + list([[0, "A <b>formal language</b> = a set of <b>strings</b> (sequences of symbols). Real languages are <b>infinite</b>, so we describe them with a <b>grammar</b> (syntax)."], [1, "<b>Syntax</b>: is the sentence well formed? &nbsp; <b>Semantics</b>: what does it mean?"], [2, "<b>Context-free grammar</b>: each expression has the same form wherever it appears. Written in <b>BNF</b> (Backus-Naur form)."]], "tight") + split(list([[3, "<b>Terminal</b> symbols: actual words (she, run, street)."], [3, "<b>Non-terminal</b> symbols: categories (N, NP, V, VP)."], [4, "A <b>start symbol</b> S."], [4, "<b>Rewrite rules</b>: left side → options on the right, | means “or”."]], "tight"), fx(5, "S → NP VP<br>NP → Pronoun | Article Noun | Article AP Noun | NP PP<br>AP → Adjective | Adjective AP<br>VP → Verb | Verb NP | VP PP<br>PP → Preposition NP", "sm code"), "even"),
          n: ["A formal language is a set of strings, where each string is a sequence of symbols. Real languages contain an infinite set of strings, so we can't list them. Instead we describe the set with a grammar, also called syntax.",
            "Syntax answers whether a sentence is well formed. Semantics answers what a well formed sentence means. A language needs both.",
            "The course uses a context-free grammar, which means each expression has the same form wherever it appears. It's written in Backus-Naur form, or BNF.",
            "BNF has four components. Terminal symbols are the actual words, like she, run and street. Non-terminal symbols are categories, like N for noun, NP for noun phrase, V for verb and VP for verb phrase.",
            "There's a start symbol, S, for sentence. And there are rewrite rules: the symbol on the left can be replaced by any option on the right, where the vertical bar means or.",
            "The slides build three grammars of increasing richness. Grammar 1 only allows short noun and verb sequences. Grammar 2 splits a sentence into a noun phrase and a verb phrase and adds articles. Grammar 3, sketched here, adds adjective phrases and prepositional phrases. Because a noun phrase can contain another noun phrase, it can produce sentences of unlimited length."] },
        { v: h("Parsing: building the tree") + split(at(0, ptree(), "ptw"), list([[0, "<b>Parsing</b>: find the phrase structure → a <b>parse tree</b>."], [1, "S → NP VP"], [2, "NP → Pronoun → <b>She</b>"], [3, "VP → VP PP"], [4, "VP → Verb NP → <b>walked a small dog</b>"], [5, "PP → Prep NP → <b>over a street</b>"], [6, "<b>Ambiguity</b>: the PP could attach to the <b>dog's NP</b>. Two valid trees."]], "tight")),
          n: ["Parsing means analysing a string of words to uncover its phrase structure, according to the rules of the grammar. The result is drawn as a parse tree, an ordered rooted tree that shows how the sentence was built from the start symbol S down to the individual words. Here's She walked a small dog over a street, using a Grammar 3 style grammar.",
            "From the top, S splits into a noun phrase and a verb phrase.",
            "The noun phrase is just a pronoun, She.",
            "The verb phrase splits into a smaller verb phrase plus a prepositional phrase.",
            "The smaller verb phrase is a verb, walked, plus a noun phrase. That noun phrase is an article, an adjective phrase and a noun: a small dog.",
            "And the prepositional phrase is a preposition plus a noun phrase: over a street. Notice the slides' three trees, She walked, She walked a small dog, and this full sentence. As the sentence gets longer the tree gets deeper, because phrases nest inside phrases.",
            "One extra observation. This grammar lets a prepositional phrase attach either to a verb phrase or to a noun phrase. So over a street could describe the walking, or the dog. Two valid trees for one sentence. That's a concrete example of the ambiguity that makes NLP hard."] }
      ] },
      { t: "Language models: n-grams", sec: [4], scenes: [
        { v: h("What a language model is") + card(0, "", "A <b>language model</b> predicts a <b>probability distribution</b> over language expressions. Three views: <b>n-grams</b>, <b>bag of words</b>, <b>word embeddings</b>.") + list([[1, "<b>n-gram</b> = a sequence of n items. <b>Unigram</b> (1), <b>bigram</b> (2), <b>trigram</b> (3). Items can be characters, words, syllables…"], [2, "Key assumption: an n-gram model is a <b>Markov chain of order n − 1</b>. Each item depends only on the <b>n − 1 items before it</b>."]], "tight") + fx(3, "P(w | history) = count(history, w) / count(history)", "c") + split(card(4, "ex", "“Mando protects” appears <b>5</b> times, followed by “Grogu” <b>3</b> times. P(Grogu | Mando protects) = 3/5 = <b>0.6</b>. (Trigram: uses the last 2 words.)"), ac(4), "even"),
          n: ["A language model predicts a probability distribution over language expressions. In plain words, it tells you how likely a piece of text is, or which word is likely to come next. The course looks at three kinds: n-gram models, the bag of words model, and word embedding models. Each trades detail for simplicity in a different way.",
            "A sequence of n written items is called an n-gram. A unigram has one item, a bigram two, and a trigram three. The items can be characters, words, syllables or any other unit, which gives character n-grams and word n-grams.",
            "The key assumption: an n-gram model behaves as a Markov chain of order n minus 1. Each item depends only on the n minus 1 items right before it, and on nothing earlier. So a bigram model looks back one word, and a trigram model looks back two.",
            "The probabilities come from counting. The probability of word w given its history is the number of times the history is followed by w, divided by the number of times the history appears at all.",
            "Here's the example from the revision notes, and it works exactly like your phone keyboard's next-word suggestions. In a corpus, Mando protects appears 5 times, and 3 of those times the next word is Grogu. So the probability of Grogu given Mando protects is 3 over 5, which is 0.6. The history is two words, so that's a trigram estimate."] },
        { v: h("Character n-grams: “excellence”") + fx(0, "P(c<sub>1:N</sub>) = Π<sub>i</sub> P(c<sub>i</sub> | c<sub>i−2:i−1</sub>) &nbsp; (trigram)", "c") + at(1, chr) + fx(1, "P(excellence) = P(e) · P(x | e) · P(c | ex) · P(e | xc) · P(l | ce) · P(l | el) · P(e | ll) · P(n | le) · P(c | en) · P(e | nc)", "sm") + list([[2, "10 letters → 10 factors. The 1st has <b>no history</b>, the 2nd has <b>one</b> letter, every later one uses <b>two</b>."], [3, "Most languages use about <b>100 characters</b>, so character models are small."]], "tight"),
          n: ["The simplest language model is a probability distribution over sequences of characters: letters, digits, punctuation and spaces. Under the trigram model, each character is conditioned on the two characters before it, and the probability of the whole string is the product of these conditional probabilities.",
            "The slide applies this to the word excellence. Write it out: P of e, times P of x given e, times P of c given e x, times P of e given x c, and so on, sliding along, up to P of e given n c at the end.",
            "Excellence has 10 letters, so there are 10 factors. The first character has no history at all, and the second has only one character before it, so the early factors use less context. Every later factor uses exactly two.",
            "Characters are a small alphabet, about a hundred symbols for most languages, so the counts are easy to collect."] },
        { v: h("Word n-grams: three practical issues") + cols(card(0, "warn", "<b>Out of vocabulary</b><br>A new word must not get probability 0. Add a special symbol <b>&lt;UNK&gt;</b> for any unknown word."), card(1, "", "<b>Tokenisation</b><br>Split text into tokens first (word or sentence tokenisation), stripping punctuation and function words like a, my, therefore."), card(2, "tip", "<b>Text generation</b><br>Predict the next word again and again. Trigram: word 3 from words 1-2, word 4 from words 2-3…")) + card(3, "bad", "Generated text often looks <b>grammatical and human</b> but has no real meaning or purpose. N-grams memorise <b>local patterns</b>, don't learn meaning, and fail on <b>unseen combinations</b>."),
          n: ["The same mechanism works on words, but the vocabulary is far bigger, at least tens of thousands of words instead of a hundred characters. That causes three issues. First, out of vocabulary words. A new word that never appeared in training must not be treated as impossible. The fix is a special symbol, written U N K, for unknown, that stands for any word outside the vocabulary.",
            "Second, tokenisation. Before a word model can be used, text has to be split into tokens. Word tokenisation gives words and sentence tokenisation gives sentences, following rules that also strip punctuation and function words such as a, my, your, therefore, and without.",
            "Third, text generation. Because the model is a Markov chain, it can generate text by predicting the next word over and over. With trigrams, the third word is drawn from a distribution based on the first two, the fourth from the second and third, and so on.",
            "The output often looks grammatical and human-sounding, yet it may carry no real meaning or purpose. N-grams memorise local patterns. They don't learn meaning, and they fail on word combinations they've never seen."] },
        { v: h("Smoothing (optional)") + card(0, "", "Training counts only <b>estimate</b> the true probabilities. <b>Smoothing</b> gives zero-count sequences a <b>small nonzero</b> probability and shrinks the others slightly, so everything still sums to 1.") + list([[1, "<b>Simplest</b>: set the probability to <b>1 / (n + 2)</b>, n = number of training observations."], [2, "<b>Back-off</b>: for a low or zero count, fall back to the <b>(n − 1)-gram</b>."]], "tight") + fx(3, "<b>Linear interpolation</b>: P̂(c<sub>i</sub> | c<sub>i−2:i−1</sub>) = λ<sub>3</sub> P(c<sub>i</sub> | c<sub>i−2:i−1</sub>) + λ<sub>2</sub> P(c<sub>i</sub> | c<sub>i−1</sub>) + λ<sub>1</sub> P(c<sub>i</sub>), &nbsp; λ<sub>3</sub> + λ<sub>2</sub> + λ<sub>1</sub> = 1", "c"),
          n: ["Smoothing is optional in the course, but quick. The training corpus only gives an estimate of the true probabilities, and we want the model to handle text it hasn't seen. Smoothing adjusts low counts so that sequences with a count of zero get a small nonzero probability, while the other counts shrink slightly so that everything still adds up to 1.",
            "The simplest approach sets the probability to 1 divided by n plus 2, where n is the number of observations in the training set.",
            "A back-off model estimates n-gram counts, and for any sequence with a low or zero count, it falls back to the n minus 1 gram. No trigram evidence? Use the bigram.",
            "Linear interpolation is a back-off style model that blends all three at once: some weight on the trigram estimate, some on the bigram, and some on the unigram. The three lambda weights add up to 1."] }
      ] },
      { t: "Bag of words", sec: [], scenes: [
        { v: h("Bag of words (BoW)") + list([[0, "Algorithms can't read text, so convert it to <b>numbers</b>. BoW = the text as a <b>bag of its words</b>: ignore grammar and <b>order</b>, keep <b>counts</b>."], [1, "R1: “My grandson loved it! So much fun!” R2: “Kind of cheap and flimsy, not worth it.”"]], "tight") + stg(0, bag, "16/1.35", "ex6") + tbl(["", "my", "grandson", "loved", "so", "much", "fun", "it", "kind", "cheap", "flimsy", "not", "worth"], [[1, "<b>Review 1</b>", "1", "1", "1", "1", "1", "1", "<b>1</b>", "0", "0", "0", "0", "0"], [2, "<b>Review 2</b>", "0", "0", "0", "0", "0", "0", "<b>1</b>", "1", "1", "1", "1", "1"]], "sm") + list([[3, "Used as a <b>feature extraction</b> tool feeding a classifier."], [4, "Careful: a stop list that deletes <b>not</b> can <b>flip</b> a review's meaning."]], "tight"),
          n: ["Machine learning algorithms can't read raw text, so text has to become numbers. The bag of words model represents a text as a bag of its words. It ignores grammar and word order, but keeps how many times each word occurs. The intuition is that the content words of a document tell you a lot about what it means.",
            "The slide uses two short product reviews. Review 1: My grandson loved it! So much fun! After removing punctuation and lower-casing, each word gets a count of 1. Picture tipping the words into a bag and shaking it. The order is gone, only the counts survive.",
            "Review 2: Kind of cheap and flimsy, not worth it. Put both on one shared vocabulary and each review becomes a vector of counts. Notice it appears in both.",
            "Because bag of words throws away syntax, context and order, it's mainly a feature extraction tool. The vectors feed a classifier, like the Naive Bayes model we'll build later.",
            "A careful point. The slide keeps words like it and not after cleaning, so what counts as a stop word depends on your list. That matters for sentiment. A list that deletes not turns not worth it into worth it, and flips the meaning of the review."] },
        { v: h("Comparing the three language model ideas") + tbl(["Model", "Unit", "Uses word order?", "Main use"], [[0, "<b>N-gram</b>", "Characters or words in sequences of n", "<b>Yes</b>, within a window of n − 1 previous items", "Next-item prediction, text generation"], [1, "<b>Bag of words</b>", "Whole text as word counts", "<b>No</b>", "Feature extraction for classifiers"], [2, "<b>Word embedding</b>", "Each word as a learned dense vector", "Only through the <b>contexts</b> a word appears in", "Similarity, analogies, features for neural models"]]),
          n: ["Here are the three ideas side by side. N-grams work on characters or words in sequences of n. They do use word order, but only inside a window of the n minus 1 previous items. They're used for predicting the next item and generating text.",
            "Bag of words treats a whole text as word counts. No order at all. It's used to extract features for classifiers.",
            "Word embeddings represent each word as a learned dense vector. Order only matters through the contexts each word appears in during training. They're used for similarity, analogies, and as features for neural models. That's next."] }
      ] },
      { t: "Representing words", sec: [3], scenes: [
        { v: h("Method 1: one-hot vectors") + split(tbl(["Word", "he", "is", "singing", "she", "dancing", "stage"], [[1, "<b>she</b>", "0", "0", "0", "<b>1</b>", "0", "0"], [1, "<b>is</b>", "0", "<b>1</b>", "0", "0", "0", "0"], [1, "<b>singing</b>", "0", "0", "<b>1</b>", "0", "0", "0"]], "sm"), list([[0, "Fix an order for the vocabulary. Each word = a vector as long as the vocabulary, with a single <b>1</b> at its position."], [1, "“She is singing” → three vectors."]], "tight"), "even") + cols(card(2, "bad", "<b>Inefficient</b>: length = vocabulary size. New words grow |V|."), card(3, "bad", "<b>No meaning</b>: every pair is equally different. Can't see that author ≈ writer."), card(4, "bad", "<b>Sparse</b>: mostly zeros, wastes space and time. Index numbers have no magnitude meaning.")),
          n: ["To let an agent work with word meanings, the meanings have to be numbers. Method 1 is the one-hot representation. Fix an order for the vocabulary. Each word becomes a vector as long as the vocabulary, with a single 1 at that word's position and 0 everywhere else.",
            "With the vocabulary he, is, singing, she, dancing, stage, the sentence She is singing becomes three vectors. She has a 1 in position 4, is in position 2, singing in position 3.",
            "The drawbacks. First, it's inefficient for large vocabularies. The vector length equals the vocabulary size, and every new word makes every vector longer.",
            "Second, no meaning is captured. Every pair of words is equally far apart, so the representation can't show that author and writer are similar.",
            "Third, the vectors are sparse, almost all zeros, which wastes space and time. And the position numbers themselves mean nothing. Word 4 isn't bigger than word 2 in any useful sense."] },
        { v: h("Method 2: distributed representation (embeddings)") + split(svg("embed", 0) + tbl(["", "One-hot", "Embedding"], [[4, "Length", "Vocabulary size", "A few hundred"], [4, "Values", "One 1, rest 0", "Real numbers"], [4, "Similarity?", "<b>No</b>", "<b>Yes</b>"], [4, "Built by", "Vocab order", "<b>Learning</b>"]], "sm"), card(0, "ana", "J. R. Firth: a word is known by the <b>company it keeps</b>.") + list([[1, "Meaning <b>spread</b> over a short vector: <b>100 to 1000</b> real numbers (−0.34, 0.40…)."], [2, "A <b>word embedding</b>: small, <b>learned</b>, similar words get <b>nearby</b> vectors."], [3, "Single dimensions have <b>no readable meaning</b>. The whole space matters."]], "tight"), "even"),
          n: ["Method 2, the distributed representation, follows a linguistic idea from J. R. Firth: a word's meaning comes from the company it keeps. Words that show up in similar contexts tend to mean similar things.",
            "Instead of one position per word, the meaning is spread across many values of a short vector, typically 100 to 1000 numbers. The values are real numbers like minus 0.34 or 0.40, not just zeros and ones.",
            "Such a vector is called a word embedding. Embeddings are much smaller than one-hot vectors for the same vocabulary, every word still gets a unique vector, and they're learned automatically from data. Similar words end up with nearby vectors, as in the picture.",
            "A caution. The individual dimensions have no human-readable meaning on their own. You can't point at number 37 and say that's the royalty dimension. What matters is the space as a whole.",
            "Here's the comparison table. One-hot: as long as the vocabulary, a single 1, no similarity, fixed by vocabulary order. Embedding: a few hundred numbers, real values everywhere, captures similarity, learned from a large text corpus."] }
      ] },
      { t: "Word2vec: skip-gram and CBOW", sec: [3], scenes: [
        { v: h("Word2vec: learn from a sliding window") + list([[0, "<b>Word2vec</b> (Google, 2013): neural nets with <b>one hidden layer</b> that map words to vectors. Trained on a big corpus, <b>no manual labels</b>."]], "tight") + tks(1, "Window 2", ["the", "+quick", "+brown", "*fox", "+jumps", "+over", "the", "lazy", "dog"]) + split(card(2, "tip", "<b>Skip-gram</b>: centre → each context word. (fox, quick), (fox, brown)…") + card(3, "", "<b>CBOW</b>: context → centre. (quick, brown, jumps, over) → fox") + fx(4, "Similar contexts → similar meanings. Loss = −log p(correct word)", "sm"), svg("w2v", 2), "even"),
          n: ["Google announced word2vec in 2013. It's a family of models that map each vocabulary word to a vector of real numbers. Each model is a small neural network with one input layer, one hidden layer and one output layer, trained on a large corpus. The labels come free from the text itself, so no one has to annotate anything.",
            "The training data comes from a sliding window. Take the quick brown fox jumps over the lazy dog. With a window of size 2 and target word fox, the context is the two words before it, quick and brown, and the two words after, jumps and over. Then the window slides one word along and repeats.",
            "The course's architecture is continuous skip-gram. Given the centre word, predict each context word. So fox produces four training pairs: fox with quick, fox with brown, fox with jumps, fox with over.",
            "The reverse is CBOW, continuous bag of words. The context words together predict the centre word. Quiz trap: CBOW predicts the centre word from the context. Skip-gram predicts the context from the centre word.",
            "Both rest on one assumption: words with similar contexts have similar meanings. Training pushes up the probability of the correct word, using the loss minus log p of the correct word, with a softmax over the whole vocabulary."] },
        { v: h("Inside the skip-gram network") + flow([[0, "x: one-hot <b>V × 1</b>"], [1, "× W (<b>V × N</b>)"], [1, "h: <b>N × 1</b>"], [2, "× W′ (<b>N × V</b>)"], [2, "u: scores <b>V × 1</b>"], [3, "softmax → y <b>V × 1</b>"]], "sm") + split(tbl(["Symbol", "Meaning"], [[0, "V", "Vocabulary size (unique words)"], [0, "x", "One-hot vector of the target word"], [1, "N", "Hidden neurons (e.g. 50 or 100, flexible)"], [1, "h", "Hidden layer = the word's <b>distributed representation</b>"], [2, "W, W′", "Input→hidden and hidden→output weights"], [3, "y", "Probability for <b>every</b> word being a context word"]], "sm"), fx(3, "y<sub>j</sub> = e<sup>u<sub>j</sub></sup> / Σ<sub>k</sub> e<sup>u<sub>k</sub></sup>", "c") + card(4, "tip", "Trained with <b>backpropagation</b> so true context words get high probability. After training, the <b>rows of W</b> are the <b>word embeddings</b>. (x is one-hot, so x × W just picks one row.)"), "even"),
          n: ["Here's the network layout using the slide's notation. V is the vocabulary size. The input x is the one-hot vector of the target word, so it's V by 1.",
            "x is multiplied by the first weight matrix W, which is V by N, giving the hidden vector h, which is N by 1. N is the number of hidden neurons, say 50 or 100, and you choose it. The values of h are the distributed representation of the word.",
            "Then h is multiplied by the second weight matrix W prime, which is N by V, giving a vector of raw scores u, one score per vocabulary word.",
            "A softmax turns those scores into probabilities y that sum to 1. Each output value is the probability that that word is a context word for the target. Softmax: e to the score, divided by the sum of e to every score.",
            "Training uses backpropagation to make the probabilities large for the true context words. Here's the neat part. Because x is one-hot, multiplying it by W just picks out one row of W. So after training, the rows of W are the word embeddings."] },
        { v: h("What trained embeddings can do") + split(fx(0, "cos(a, b) = a · b / (‖a‖ ‖b‖)", "c") + fx(1, "a = [1, 2, 0], b = [2, 3, 1]<br>a · b = 2 + 6 + 0 = 8<br>‖a‖ = √5 ≈ 2.236, &nbsp; ‖b‖ = √14 ≈ 3.742<br>cos = 8 / 8.367 ≈ <b>0.956</b> (very similar)", "sm"), list([[2, "<b>Similar words</b>: book → books, essay, memoir, novella, anthology, autobiography."], [3, "<b>Vector arithmetic</b>: king − man captures a relationship. king − man + woman lands closest to <b>queen</b>."], [4, "Cautions: the numbers mean little on their own, and why word2vec works so well is still <b>poorly understood</b>."]], "tight"), "even"),
          n: ["Closeness between embeddings, and so semantic similarity, is measured with cosine similarity: the dot product of the two vectors, divided by the product of their lengths. It's 1 when they point the same way, 0 when they're at right angles.",
            "A quick example. a is 1, 2, 0 and b is 2, 3, 1. The dot product is 2 plus 6 plus 0, which is 8. The length of a is root 5, about 2.236. The length of b is root 14, about 3.742. Multiply those to get 8.367, and 8 divided by 8.367 is about 0.956. Very similar.",
            "So what can trained embeddings do? Find similar words. For book, the nearest words include books, essay, memoir, novella, anthology and autobiography.",
            "And do arithmetic on relationships. The difference between king and man captures something like royalty. Add that difference to woman and you land closest to queen.",
            "Two cautions from the notes. The numbers in a vector mean little by themselves, since they're an abstract position in a space. And the reasons word2vec works so well are still poorly understood."] }
      ] },
      { t: "Text classification with Naive Bayes", sec: [5], scenes: [
        { v: h("Two ways to classify text") + cols(card(0, "", "<b>Approach 1: language modelling</b><br>Train one n-gram model on positive texts, one on negative. Classify: pick c maximising <b>P(message | c) × P(c)</b>. P(c) = share of training messages in class c."), card(1, "tip", "<b>Approach 2: machine learning</b><br>Message → <b>feature vector</b> x → classifier: k-NN, SVM, decision tree, logistic regression, RNN (LSTM), or <b>Naive Bayes</b> (this week).")) + list([[2, "Typical tasks: sentiment, <b>language identification</b> (over <b>99%</b> accuracy, occasionally confusing close languages), genre, spam."]], "tight"),
          n: ["Text classification decides which of a predefined set of classes a text belongs to. The slide gives two approaches. Approach 1 uses language models. Train one n-gram model on the positive texts and another on the negative texts. To classify a new message, pick the class c that maximises the probability of the message given c, times the probability of c. P of c is estimated by counting what share of the training messages belong to each class.",
            "Approach 2 is machine learning. Turn the message into feature and value pairs, a feature vector x, then apply a classifier to it. Options include k nearest neighbours, SVM, decision trees, logistic regression, and RNNs like the LSTM. The first four were in the machine learning module. This module covers Naive Bayes.",
            "The typical tasks are sentiment analysis, language identification, where systems exceed 99 percent accuracy and only occasionally confuse closely related languages, genre classification and spam detection."] },
        { v: h("The Naive Bayes model") + fx(0, "P(C<sub>k</sub> | x<sub>1</sub>, …, x<sub>n</sub>) = (1/Z) · P(C<sub>k</sub>) · Π<sub>i</sub> P(x<sub>i</sub> | C<sub>k</sub>)", "c") + list([[1, "Applies <b>Bayes' theorem</b>: a conditional probability model."], [2, "<b>Naive</b> assumption: features x<sub>1</sub>…x<sub>n</sub> are <b>independent given the class</b>. In text: words don't affect each other once you know the class."]], "tight") + fx(3, "Z = Σ<sub>k</sub> P(C<sub>k</sub>) Π<sub>i</sub> P(x<sub>i</sub> | C<sub>k</sub>) &nbsp; (the <b>evidence</b>)", "sm") + cols(card(4, "tip", "Z is the <b>same for every class</b>, so ignore it when comparing, and use it only to <b>normalise</b> at the end."), card(5, "ok", "<b>MAP rule</b>: ŷ = argmax<sub>k</sub> P(C<sub>k</sub>) Π<sub>i</sub> P(x<sub>i</sub> | C<sub>k</sub>)")),
          n: ["Naive Bayes applies Bayes' theorem to predict the class of an unseen example. The probability of class k given the features equals one over Z, times the prior probability of the class, times the product of each feature's probability given the class.",
            "At heart it's a conditional probability model.",
            "Its defining naive assumption: all the features are mutually independent once the class is known. For text, each word is a feature, so we pretend words don't influence each other once we know whether the review is positive or negative. That's clearly false in real language, yet it still works well in practice.",
            "Z is called the evidence. It's the sum, over all classes, of prior times product of likelihoods.",
            "Z depends only on the features, so once the feature values are known it's the same number for every class. That's why we can ignore it when comparing classes, and only use it at the end to turn the scores into proper probabilities.",
            "The classifier then applies the maximum a posteriori rule, or MAP rule: choose the class with the highest value of prior times product of likelihoods."] },
        { v: h("Derivation in six steps (optional)") + list([[0, "1. Bayes: P(C<sub>k</sub> | x) = P(C<sub>k</sub>) P(x | C<sub>k</sub>) / P(x)"], [1, "2. P(x) doesn't depend on the class → P(C<sub>k</sub> | x) ∝ P(C<sub>k</sub>, x<sub>1</sub>, …, x<sub>n</sub>) (the joint)"], [2, "3. <b>Chain rule</b>: = P(x<sub>1</sub> | x<sub>2</sub>, …, x<sub>n</sub>, C<sub>k</sub>) · P(x<sub>2</sub> | x<sub>3</sub>, …, x<sub>n</sub>, C<sub>k</sub>) ⋯ P(x<sub>n</sub> | C<sub>k</sub>) · P(C<sub>k</sub>)"], [3, "4. <b>Naive</b>: P(x<sub>i</sub> | x<sub>i+1</sub>, …, x<sub>n</sub>, C<sub>k</sub>) = P(x<sub>i</sub> | C<sub>k</sub>)"], [4, "5. Substitute: P(C<sub>k</sub> | x) ∝ P(C<sub>k</sub>) Π<sub>i</sub> P(x<sub>i</sub> | C<sub>k</sub>)"], [5, "6. Restore Z for equality, then apply the <b>MAP</b> rule: pick the largest."]]),
          n: ["The derivation is optional, but it's six short steps. Step 1: apply Bayes' theorem. The probability of the class given the features is the prior times the likelihood, divided by the probability of the features.",
            "Step 2: the denominator doesn't depend on the class, and the features are given, so it's effectively a constant. Only the numerator matters, and that equals the joint probability of the class and all the features.",
            "Step 3: expand the joint with the chain rule, which applies the definition of conditional probability over and over. x 1 given everything after it and the class, times x 2 given everything after it and the class, and so on, down to x n given the class, times the prior.",
            "Step 4: apply the naive assumption. Given the class, each feature is independent of the features after it, so each long conditional collapses to just P of x i given the class.",
            "Step 5: substitute back. The posterior is proportional to the prior times the product of single-feature probabilities. The proportional sign hides the constant Z.",
            "Step 6: restore Z to get the equality form, then the classifier applies the MAP rule and picks the class with the highest value."] },
        { v: h("Worked example: “my grandson loved it”") + split(tbl(["Word", "P(w | +)", "P(w | −)"], [[0, "<i>prior</i>", "0.49", "0.51"], [0, "my", "0.30", "0.20"], [0, "grandson", "0.01", "0.02"], [0, "loved", "<b>0.32</b>", "<b>0.08</b>"], [0, "it", "0.30", "0.40"]], "sm") + at(1, scale) + card(5, "ana", "<b>loved</b> is <b>4×</b> more likely in positive text and outweighs the slight negative prior."), fx(1, "S<sub>+</sub> = 0.49 × 0.30 × 0.01 × 0.32 × 0.30 = <b>0.00014112</b>", "sm") + fx(2, "S<sub>−</sub> = 0.51 × 0.20 × 0.02 × 0.08 × 0.40 = <b>0.00006528</b>", "sm") + fx(3, "Z = 0.00014112 + 0.00006528 = 0.0002064<br>P(+ | text) = 0.00014112 / 0.0002064 ≈ <b>0.684</b><br>P(− | text) ≈ <b>0.316</b>", "sm") + pbar(4, 0.684, "positive 0.684", "negative 0.316") + card(6, "warn", "Slide rounds S<sub>−</sub> to 0.000064 → 0.688 / 0.312. Same decision."), "even"),
          n: ["The main worked example: what's the probability that my grandson loved it is positive? Tokenise into my, grandson, loved and it. With bag of words each word is a feature, so n is 4, and there are 2 classes. The slide gives the priors, 0.49 positive and 0.51 negative, and the probability of each word in each class. Normally you'd estimate these by counting in a labelled training set.",
            "Step 1: multiply prior and word probabilities for each class. Positive: 0.49 times 0.30 times 0.01 times 0.32 times 0.30. That's 0.00014112.",
            "Negative: 0.51 times 0.20 times 0.02 times 0.08 times 0.40. That's 0.00006528.",
            "Step 2: normalise. These products are only proportional to the true probabilities, so divide by Z, their sum, which is 0.0002064. Positive gets 0.00014112 over 0.0002064, about 0.684. Negative gets about 0.316.",
            "Step 3: the decision rule. Positive is larger, so the review is classified positive.",
            "Why does positive win? The prior slightly favours negative, 0.51 against 0.49. But loved is four times as likely in positive text, 0.32 against 0.08, and that single word pulls the whole sentence to the positive side. That's the strength of Naive Bayes. It reacts to words that are far more common in one class than the other.",
            "An arithmetic check. The slide rounds the negative product to 0.000064, which gives 0.688 and 0.312. The exact figure moves the numbers slightly but the decision is the same. If a marking scheme copies the slide, quote the slide's figures and mention the rounding."] },
        { v: h("The zero probability problem") + card(0, "bad", "If “grandson” never appeared in any positive training text, P(grandson | +) = <b>0</b>, and the whole positive product becomes <b>0</b>, whatever the other words say." + zero) + split(card(1, "", "Fix 1: <b>ignore</b> that feature.") + card(1, "tip", "Fix 2: <b>additive smoothing</b>: add a small α to every count."), fx(2, "Laplace: P(x | c) = (count(x in c) + 1) / (T<sub>c</sub> + |V|)", "sm") + fx(3, "“heartwarming”: 6 times, T<sub>+</sub> = 20, |V| = 6<br>(6 + 1) / (20 + 6) = 7/26 ≈ <b>0.27</b>", "sm"), "even") + card(4, "ex", "11 positive, 9 negative reviews → P(+) = <b>0.55</b>, P(−) = <b>0.45</b>. S<sub>+</sub> = 0.000328, S<sub>−</sub> = 0.000640 → 0.000328 / 0.000968 ≈ <b>0.34</b> → <b>negative</b>."),
          n: ["Now a real danger. Suppose no positive sentence in the training data ever contained grandson. Then P of grandson given positive is zero. Because the probabilities are multiplied, the whole positive score collapses to zero, no matter how glowing every other word is.",
            "Two ways to handle it. Ignore that feature, or use additive smoothing, which adds a small value alpha to every count so that no probability is exactly zero.",
            "With alpha equal to 1 it's called Laplace or add-one smoothing. The probability of word x given class c is its count in c plus 1, divided by T c, the total word count in that class, plus the vocabulary size.",
            "Example from the revision notes. Heartwarming appears 6 times in positive reviews. Positive reviews contain 20 words in total, and the vocabulary has 6 words. So it's 6 plus 1, over 20 plus 6, which is 7 over 26, about 0.27.",
            "And the revision notes' full example: 11 positive and 9 negative training reviews give priors 0.55 and 0.45. After multiplying, S plus is 0.000328 and S minus is 0.000640. Normalise: 0.000328 over 0.000968 is about 0.34, so the prediction is negative. Same method, different words, different answer. Always finish with the normalisation and the comparison."] }
      ] },
      { t: "Information retrieval (optional)", sec: [], scenes: [
        { v: h("What an IR system is") + split(list([[0, "<b>IR</b>: find documents relevant to a <b>query</b> (web search)."], [1, "Parts: <b>corpus</b>, <b>queries</b>, <b>result set</b>, <b>presentation</b>."], [2, "<b>Boolean model</b>: each word true/false. Relevant only if the query expression is <b>true</b>."], [3, "<b>Word count models</b>: score(doc, query) → number. Highest = most relevant."]], "tight"), fx(4, "TF(q<sub>i</sub>, d<sub>j</sub>) = number of times q<sub>i</sub> appears in d<sub>j</sub>", "sm") + card(4, "bad", "Raw TF mostly rewards words common in <b>all</b> English (the, and), which say nothing about a document.") + fx(5, "IDF(q<sub>i</sub>) = log( N / DF(q<sub>i</sub>) )", "sm") + card(5, "", "N = documents in the corpus, DF = documents containing the word. Rare word → <b>high</b> IDF."), "even"),
          n: ["Information retrieval is optional in the course, but it's very examinable style material. It finds documents relevant to a user need expressed as a query. Typing into a web search engine is the everyday example.",
            "An IR system has four parts. A corpus of documents, where you decide what counts as a document: a paragraph, a page, or a multi-page text. Queries written in a query language. A result set of documents judged relevant. And a presentation of that result set to the user.",
            "The earliest systems used a Boolean keyword model. Each word is a true or false feature: does it occur in the document? A query is a Boolean expression over those features, and a document is relevant only if the expression comes out true.",
            "Most modern systems instead score each document with a function of the document and the query, and the highest scores are most relevant. The idea is that key terms repeat.",
            "The simplest score is term frequency, TF: how many times a query word appears in a document. But raw TF has a flaw. It mostly rewards words that are common in English in general, like the and and, which say nothing about what a particular document is about.",
            "Inverse document frequency fixes that. IDF is the log of N, the number of documents, divided by DF, the number of documents containing the word. A word in every document gets log of 1, which is zero. A rare word gets a high IDF."] },
        { v: h("TF-IDF and how a search actually runs") + fx(0, "TF-IDF(q<sub>i</sub>, d<sub>j</sub>) = TF(q<sub>i</sub>, d<sub>j</sub>) × IDF(q<sub>i</sub>)", "c") + split(tbl(["Word in doc d", "TF", "DF (N = 1000)", "IDF = log<sub>10</sub>(N/DF)", "TF-IDF"], [[1, "transformer", "4", "10", "2", "<b>8</b>"], [2, "the", "30", "1000", "0", "<b>0</b>"]], "sm") + card(3, "tip", "High when a word is <b>frequent in this document</b> and <b>rare across the corpus</b>. Remove <b>stop words</b> first."), list([[4, "Scoring every document is too slow. Build an <b>index</b> in advance: for each word, its <b>hit list</b> (documents containing it)."], [5, "Query arrives → <b>intersect</b> the query words' hit lists → score only those documents."]], "tight"), "even"),
          n: ["Multiply the two and you get TF-IDF, term frequency times inverse document frequency.",
            "An illustration, using log base 10. In a corpus of 1000 documents, the word transformer appears 4 times in our document, and in only 10 documents overall. Its IDF is log of 1000 over 10, which is log of 100, which is 2. So TF-IDF is 4 times 2, which is 8.",
            "The word the appears 30 times in our document, but it's in all 1000 documents. IDF is log of 1, which is 0. So TF-IDF is 0, even though it's the most frequent word.",
            "That's exactly the behaviour we want. A word scores high when it's common in this document and appears in few documents. It scores low when it's rare in the document, or common everywhere. And cleaning comes first: remove stop words and function words like the, by, and, which and yet, so the remaining content words better show what each document is about.",
            "In practice, scoring every document in the corpus for every query would be far too slow. So the system builds an index ahead of time, listing for each vocabulary word the documents that contain it. That list is the word's hit list.",
            "When a query arrives, the system intersects the hit lists of the query words and scores only the documents in that intersection."] },
        { v: h("Evaluating IR: precision, recall, F") + stg(0, net, "16/2.4", "ex6") + split(tbl(["", "In result set", "Not in result set"], [[0, "<b>Relevant</b>", "<b>30</b>", "20"], [0, "<b>Not relevant</b>", "10", "40"]]) + fx(1, "Precision = 30 / (30 + 10) = <b>0.75</b>", "sm") + fx(2, "Recall = 30 / (30 + 20) = <b>0.60</b>", "sm") + fx(3, "F = 2PR / (P + R) = 2(0.75)(0.60) / 1.35 ≈ <b>0.667</b>", "sm ok"), list([[1, "<b>Precision</b>: of what you <b>returned</b>, how much is relevant?"], [2, "<b>Recall</b>: of all <b>relevant</b> documents, how many did you return?"], [3, "<b>F</b>: <b>harmonic mean</b>, closer to the <b>lower</b> value."], [4, "Slide: 1 − precision = “FPR”. Standard FPR = 10/50 = <b>0.2</b>."], [5, "Web: recall is <b>sampled or dropped</b>. Report <b>P@10</b>, <b>P@50</b>."]], "tight"), "even"),
          n: ["Two standard measures judge an IR system. Think of the search as a fishing net: the fish are relevant documents and the old boots are irrelevant ones. Here's the worked example: a corpus of 100 documents and one query. 30 relevant documents were returned, 20 relevant ones were missed, 10 irrelevant ones were returned, and 40 irrelevant ones were correctly left out.",
            "Precision, also called positive predictive value, is the share of returned documents that are actually relevant. 40 were returned and 30 were relevant, so precision is 0.75.",
            "Recall, also called sensitivity, is the share of all relevant documents that got returned. There are 50 relevant documents and we found 30, so recall is 0.60.",
            "The F score combines them as their harmonic mean: 2 times P times R, over P plus R. 2 times 0.75 times 0.60 is 0.9, divided by 1.35, about 0.667. Notice it sits between them but closer to the lower one. That's what a harmonic mean does, and it stops a system from looking good by maxing just one measure.",
            "A terminology watch. The slide calls 1 minus precision the false positive rate. In standard usage the false positive rate is the share of all non-relevant documents that get retrieved, here 10 out of 50, or 0.2. Treat the slide's label as course shorthand. The 1 minus recall figure, 0.4, is the standard false negative rate.",
            "And in a huge collection like the web, nobody can check every page for relevance, so recall is estimated by sampling or dropped. Instead, precision is reported at cut-offs, like P at 10 for the top 10 results, or P at 50."] }
      ] },
      { t: "Sequences and RNNs", sec: [0, 1], scenes: [
        { v: h("Why sequences need memory") + split(list([[0, "<b>Sequence</b> = observations + <b>meaningful order</b>. Later steps depend on earlier ones."], [1, "A sequence model should: handle <b>variable length</b>, keep <b>order</b>, carry <b>context</b>, <b>share parameters</b> across time."], [2, "A feedforward network has <b>no state</b>. An <b>RNN</b> has a <b>hidden state</b> h<sub>t</sub> = memory of earlier inputs."]], "tight") + fx(3, "h<sub>t</sub> = tanh(W<sub>hh</sub> h<sub>t−1</sub> + W<sub>xh</sub> x<sub>t</sub> + b) &nbsp; ŷ<sub>t</sub> = W<sub>hy</sub> h<sub>t</sub>", "sm") + card(4, "tip", "h<sub>0</sub> = zeros (or learned). The <b>same cell and weights</b> are reused every step. Unrolling copies the <b>computation</b>, not the parameters."), svg("rnnCell", 3), "even"),
          n: ["Now the sequence side, which the revision notes for this week cover. A sequence is a set of observations with a meaningful order. Positions aren't interchangeable. Later steps depend on earlier ones. Not worth it and worth it, not, mean very different things.",
            "So a sequence model should handle variable length inputs, keep the order, carry context from earlier steps, and share its parameters across time so it works at any position.",
            "A feedforward network has no state. It sees one input and forgets it. A recurrent neural network, or RNN, keeps a hidden state h t, which acts as a memory of everything it has read so far.",
            "The update: the new hidden state is tanh of the recurrent weight times the previous state, plus the input weight times the current input, plus a bias. The output at that step is another weight times the hidden state.",
            "The starting state h 0 is usually zeros, or learned. And the key exam point: the same cell with the same weights is reused at every time step. When we draw the network unrolled over time, we copy the computation, not the parameters."] },
        { v: h("Input and output shapes") + split(svg("seqTypes", 0), tbl(["Type", "Example"], [[1, "<b>One-to-many</b>", "Image captioning (one image → words), music from a seed"], [2, "<b>Many-to-one</b>", "Sentiment classification, ECG → diagnosis"], [3, "<b>Many-to-many</b>", "Machine translation"]]), "even"),
          n: ["Sequence tasks come in different shapes, depending on how many inputs and outputs there are.",
            "One-to-many: one input, a sequence out. Image captioning takes one image and produces a sentence of words. Generating music from a seed is another.",
            "Many-to-one: a sequence in, one output. Sentiment classification reads a whole review and outputs one label. Reading an ECG signal and outputting a diagnosis is another.",
            "Many-to-many: a sequence in and a sequence out, like machine translation."] },
        { v: h("Calculation: one hidden-state update") + split(list([[0, "1. Input × <b>input weight</b>."], [1, "2. Previous state × <b>recurrent weight</b>."], [2, "3. <b>Add</b> them (add bias only if given)."], [3, "4. Apply the activation (tanh) using the <b>supplied value</b>."]], "tight") + card(5, "warn", "The sum before tanh is <b>not</b> the answer. Don't swap x and h<sub>prev</sub>: each keeps its own weight."), fx(0, "x = 2, w<sub>x</sub> = 0.5, h<sub>prev</sub> = 0.4, w<sub>h</sub> = 0.25, no bias", "sm") + fx(2, "sum = 0.5 × 2 + 0.25 × 0.4 = 1.0 + 0.1 = <b>1.1</b>", "sm") + fx(3, "tanh(1.1) = 0.800 (given) → h<sub>t</sub> = <b>0.800</b>", "sm ok") + fx(4, "Practice: x = 1, w<sub>x</sub> = 0.6, h<sub>prev</sub> = 0.5, w<sub>h</sub> = 0.8, b = 0.1<br>sum = 0.6 + 0.4 + 0.1 = <b>1.1</b>", "sm"), "even"),
          n: ["Here's the calculation the quiz uses. Step 1: multiply the current input by the input weight. Our example: x is 2, input weight 0.5, previous state 0.4, recurrent weight 0.25, no bias.",
            "Step 2: separately multiply the previous hidden state by the recurrent weight.",
            "Step 3: add them, and add a bias only if one is given. 0.5 times 2 is 1.0. 0.25 times 0.4 is 0.1. The sum is 1.1.",
            "Step 4: apply the activation, tanh, using the lookup value you're given. tanh of 1.1 is given as 0.800, so the new hidden state is 0.800.",
            "Try this one. x is 1, input weight 0.6, previous state 0.5, recurrent weight 0.8, bias 0.1. That's 0.6 plus 0.4 plus 0.1, a pre-activation sum of 1.1.",
            "The two classic mistakes: stopping at the sum, which isn't the final answer, and swapping x and the previous state so they get the wrong weights."] }
      ] },
      { t: "Training RNNs", sec: [2], scenes: [
        { v: h("Backpropagation through time (BPTT)") + flow([[0, "Sum the losses over all time steps"], [0, "<b>Backpropagate through time</b>"], [0, "Update the <b>shared</b> weights"]], "sm") + list([[1, "The gradient for an early step multiplies by W<sub>hh</sub> and tanh′ <b>once per step</b> it travels back."], [2, "Factors below 1 → <b>vanishing</b> gradient. Above 1 → <b>exploding</b> gradient."]], "tight") + cols(fx(2, "0.5<sup>10</sup> ≈ 0.001" + vg(0.5, 2, ""), "sm bad"), fx(2, "1.5<sup>10</sup> ≈ 57.7" + vg(1.5, 2, "ex5"), "sm bad")) + cols(card(3, "", "Long-range clues get <b>lost</b>."), card(4, "tip", "Exploding → <b>gradient clipping</b>. Vanishing → <b>gated cells</b> (LSTM, GRU).")),
          n: ["To train an RNN, sum the losses over all time steps, backpropagate through the unrolled network, which is called backpropagation through time, and update the shared weights.",
            "The trouble: the gradient for an early time step has to travel back through every later step, and each step multiplies it by the recurrent weight and by the derivative of tanh.",
            "Multiply by something smaller than 1 again and again and the gradient vanishes. Bigger than 1 and it explodes.",
            "0.5 to the power 10 is about 0.001. 1.5 to the power 10 is about 58. Over long sequences it's even worse. With vanishing gradients, long-range clues get lost, so the model can't connect the end of a long sentence to something at the start.",
            "The fixes. For exploding gradients, use gradient clipping, which caps the gradient's size. For vanishing gradients, use gated cells like the LSTM or GRU, from the neural networks week, where a learned gate controls how much information passes to the next step."] }
      ] },
      { t: "Attention", sec: [6], scenes: [
        { v: h("Attention: query, key, value") + split(svg("attention", 0), list([[0, "Each token <b>retrieves the context it needs</b>."], [1, "<b>Query (Q)</b>: what I'm looking for."], [2, "<b>Key (K)</b>: compact description used for <b>matching</b>."], [3, "<b>Value (V)</b>: the full information <b>returned</b> after a match."]], "tight") + card(4, "ana", "Library: question = <b>query</b>, titles = <b>keys</b>, contents = <b>values</b>. Read more from the best matches, blend."), "even"),
          n: ["RNNs squeeze everything into one hidden state that has to travel step by step. Attention takes a different route. Each token retrieves the context it needs by looking directly at the relevant tokens, however far away they are.",
            "Three roles. The query is what I'm looking for.",
            "The key is a compact description of each token, used for matching against the query. Quiz point: keys are what get matched.",
            "The value is the full information that gets returned after a match.",
            "The analogy: a library search. Your question is the query. Book titles are the keys. Book contents are the values. You read a bit of every book, more from the books whose titles match your question best, and blend what you read into one answer."] },
        { v: h("The attention formula, step by step") + fx(0, "score<sub>i</sub> = q · k<sub>i</sub> &nbsp; (scaled by √d<sub>k</sub>)", "sm") + fx(1, "weights = softmax(scores) → all positive, <b>sum to 1</b>", "sm") + fx(2, "output = Σ<sub>i</sub> weight<sub>i</sub> × v<sub>i</sub>", "sm") + fx(3, "Attention(Q, K, V) = softmax(QK<sup>T</sup> / √d<sub>k</sub>) V", "c ok") + split(fx(4, "Scores 2, 1, 0: &nbsp; e<sup>2</sup> = 7.389, e<sup>1</sup> = 2.718, e<sup>0</sup> = 1, sum 11.107<br>weights ≈ <b>0.665, 0.245, 0.090</b>", "sm") + at(4, `<div class="smx5">${[["key 1", 2, 66.5], ["key 2", 1, 24.5], ["key 3", 0, 9]].map(([n, sc, p]) => `<div class="brow"><em>${n} <small>score ${sc}</small></em><div class="trk">${bar({ 4: p }, "g")}</div><i>${(p / 100).toFixed(3)}</i></div>`).join("")}</div>`), card(5, "", "Why √d<sub>k</sub>? Big dot products push softmax to near 0/1, which gives tiny gradients. Scaling keeps them moderate."), "even"),
          n: ["Step 1: score each token by the dot product of the query with that token's key. A big dot product means a good match. In practice the score is divided by the square root of d k, the key length.",
            "Step 2: turn the scores into weights with softmax. The weights are all positive and sum to 1.",
            "Step 3: the output is the weighted sum of the value vectors.",
            "In matrix form for every token at once: attention of Q, K, V equals softmax of Q times K transpose, over root d k, times V.",
            "A quick softmax example. Scores 2, 1 and 0. e squared is 7.389, e to the 1 is 2.718, e to the 0 is 1. They add to 11.107. Divide each by that and the weights are about 0.665, 0.245 and 0.090. They sum to 1.",
            "Why divide by root d k? With long vectors, dot products get large, and softmax of large numbers is almost all zeros and one 1. That gives tiny gradients. Scaling keeps the scores in a sensible range."] },
        { v: h("Calculation: weighted value aggregation") + split(list([[0, "1. Multiply <b>every component</b> of value vector 1 by weight 1."], [1, "2. Same for each other value vector."], [2, "3. <b>Add</b> corresponding components."], [3, "Output length = <b>value vector length</b>."]], "tight") + at(0, vecs) + card(5, "bad", "Use <b>all</b> weights. Don't just pick the biggest-weight vector, and don't add unweighted vectors."), fx(0, "weights 0.3, 0.7 &nbsp; values [2, 0], [0, 2]", "sm") + fx(1, "0.3 × [2, 0] = [0.6, 0] &nbsp; 0.7 × [0, 2] = [0, 1.4]", "sm") + fx(2, "output = [0.6 + 0, 0 + 1.4] = <b>[0.6, 1.4]</b>", "sm ok") + fx(4, "Practice: weights 0.5, 0.25, 0.25, values [4, 0], [0, 4], [8, 8]<br>x: 2 + 0 + 2 = 4, &nbsp; y: 0 + 1 + 2 = 3 → <b>[4, 3]</b>", "sm"), "even"),
          n: ["The exam calculation. Weights 0.3 and 0.7, value vectors 2, 0 and 0, 2. Step 1: multiply every component of value vector 1 by weight 1. 0.3 times 2, 0 gives 0.6, 0.",
            "Step 2: do the same for the other value vectors. 0.7 times 0, 2 gives 0, 1.4.",
            "Step 3: add corresponding components. 0.6 plus 0 is 0.6. 0 plus 1.4 is 1.4. The output is 0.6, 1.4.",
            "The output always has the same length as each value vector.",
            "Practice: weights 0.5, 0.25 and 0.25. Values 4, 0, then 0, 4, then 8, 8. First component: 0.5 times 4 is 2, plus 0, plus 0.25 times 8 is 2, total 4. Second: 0, plus 0.25 times 4 is 1, plus 0.25 times 8 is 2, total 3. Output 4, 3.",
            "The two classic mistakes: picking only the vector with the biggest weight, and adding the value vectors without weighting them. Use every weight."] }
      ] },
      { t: "Self-attention and Transformers", sec: [7], scenes: [
        { v: h("Self-attention and the Transformer") + list([[0, "<b>Self-attention</b>: Q, K and V all come from the <b>same sequence</b>, so every token builds a <b>context-aware</b> representation."], [1, "Question answering: the <b>question</b> gives the query, the <b>document tokens</b> give keys (matching) and values (aggregation)."]], "tight") + cols(card(2, "", "<b>Multi-head attention</b><br>Several heads learn <b>different attention patterns</b> in parallel."), card(3, "warn", "<b>Positional encoding</b><br>Attention has <b>no built-in order</b>, so add position info to the embeddings.")) + card(4, "tip", "<b>Transformer</b>: built from attention, <b>no recurrence</b> → processes all positions <b>in parallel</b>, handles <b>long-range</b> links. The basis of <b>LLMs</b>."),
          n: ["In self-attention, the queries, keys and values all come from the same sequence. So every token looks at every other token in its own sentence and builds a context-aware representation. In the bank by the river, bank attends to river and its meaning shifts towards the river edge.",
            "In question answering, the question supplies the query, and the document's tokens supply the keys for matching and the values for aggregation.",
            "Multi-head attention runs several attention heads side by side. Each head learns its own pattern. One might track grammar links, another might track which noun a pronoun refers to.",
            "Positional encoding. Attention on its own is a weighted sum, and a sum doesn't care about order. Dog bites man and man bites dog would look the same. So position information is added to the embeddings. That's a quiz question: positional encoding is needed because attention alone has no sense of word order.",
            "Put these together and you get the Transformer. It's built from attention with no recurrence, so it processes all positions in parallel instead of one step at a time, and it links distant words directly. It's the basis of today's large language models."] }
      ] },
      { t: "Recap and exam checklist", sec: [], scenes: [
        { v: h("Exam checklist") + split(list([[0, "<b>Pipeline</b>: <b>tokenise</b> = words. Stem (rough) vs lemmatise (real word)."], [1, "<b>Grammar</b>: terminals, non-terminals, S, rules. PP attachment = ambiguity."], [2, "<b>N-gram</b>: Markov order n − 1. count(history, w) / count(history). &lt;UNK&gt;."], [3, "<b>BoW</b>: counts. <b>One-hot</b>: sparse, no similarity. <b>Embeddings</b>: dense, learned."], [4, "<b>Skip-gram</b>: centre → context. <b>CBOW</b>: context → centre. Rows of W."]], "tight"), list([[5, "<b>Naive Bayes</b>: prior × Π likelihoods, <b>normalise</b>, max. Laplace (n + 1)/(T<sub>c</sub> + |V|)."], [6, "<b>TF-IDF</b> = TF × log(N/DF). P, R, F = 2PR/(P + R)."], [7, "<b>RNN</b>: tanh(w<sub>x</sub>x + w<sub>h</sub>h<sub>prev</sub> + b), shared weights. Vanishing → LSTM/GRU."], [8, "<b>Attention</b>: keys match, values return, weights sum to 1. Positional encoding."]], "tight"), "even"),
          n: ["Let's recap for the exam. The pipeline: segment, tokenise, remove stop words, stem or lemmatise, tag parts of speech and named entities, then learn. Tokenisation gets the words out of a sentence. Stemming is a rough chop, lemmatisation returns a real word.",
            "Grammar: a context-free grammar in BNF has terminals, non-terminals, a start symbol and rewrite rules. A parse tree shows the structure, and a prepositional phrase that can attach in two places shows ambiguity.",
            "N-grams are Markov chains of order n minus 1. Probability is the count of history then word, over the count of history. Unknown words use the U N K symbol, and smoothing uses back-off or interpolation.",
            "Bag of words keeps counts and drops order. One-hot vectors are long, sparse, and blind to similarity. Embeddings are short, dense and learned, with similar words close together.",
            "Skip-gram predicts the context from the centre word, CBOW predicts the centre from the context. After training, the rows of W are the embeddings, compared with cosine similarity.",
            "Naive Bayes: for each class, prior times the product of word likelihoods, normalise by Z, and pick the biggest. Use Laplace smoothing to avoid a zero wiping out the product.",
            "TF-IDF is term frequency times log of N over document frequency. Precision is relevant returned over everything returned, recall is relevant returned over everything relevant, and F is their harmonic mean.",
            "RNNs reuse the same weights at every step: multiply, add, then apply tanh. Training uses backpropagation through time, with vanishing gradients fixed by LSTM or GRU gates and exploding gradients fixed by clipping.",
            "And attention: keys are matched, values are returned, the softmax weights sum to 1, and the output is the weighted sum of all the values. Transformers add positional encoding because attention has no sense of order. Now go try the quiz for this week. Good luck."] }
      ] }
    ]
  };
})();
